UPDATE c2k_department
SET parent_id=NULLIF(#{row.parentId},''),name=#{row.name},sort_order=#{row.sortOrder},enabled=#{row.enabled},revision=revision+1
WHERE tenant_id=#{tenant} AND id=#{id} AND revision=#{row.revision}

